update_rule.pseudocode:
for each location L (type != 'home'):
  entrants = sample visitors based on MobilityAndLocationUse flows and L.foot_traffic_rate
  for each person i in entrants:
    check = (random() < admission_check_probability * enforcement_strength * agent.government.enforcement_strength)
    if check and L.mask_policy == 'required' and i.adoption_state == 0:
      # Admission denial
      admit = False
      # Enforcement with probability
      if random() < enforcement_probability:
        issue fine = fine_amount; collect with prob fine_collection_rate
    else:
      admit = True
    record compliance observation = i.adoption_state by L.type

if t == mask_mandate_start_day: agent.government.policy_level = max(agent.government.policy_level, 1)
if t % policy_adjust_interval_days == 0:
  if latest adoption_rate < 0.6: agent.government.policy_level = min(3, agent.government.policy_level + 1)
  else if latest adoption_rate > 0.8: agent.government.policy_level = max(0, agent.government.policy_level - 1)
